var o=[{title:`Molte cause, molte risposte`,text:`Le persone avvertono fastidio alla schiena per ragioni diverse, e anche sintomi simili possono avere cause diverse. Alcune persone tollerano bene la flessione, mentre altre preferiscono un tronco più neutro. L’esercizio migliore per te dipende da sintomi, capacità, esperienza ed eventuali consigli del tuo medico.`},{title:`Gestire le richieste`,text:`Esercitati a contrarre senza trattenere il respiro troppo a lungo, impara un hinge controllato con un peso leggero e prova esercizi con appoggio o a terra quando fanno per te. Un delicato bird dog o dead bug allena il controllo del tronco senza pesi pesanti. Nessuna postura singola garantisce sicurezza, e mantenere una «colonna neutra» non significa bloccare ogni normale movimento della colonna.`},{title:`Progredire nel tempo`,text:`Se ti senti a tuo agio, rendi l’allenamento lentamente più difficile aggiungendo ripetizioni, range o carico. Annota come si sente la schiena durante e dopo le sessioni. Se i sintomi peggiorano, rendi le cose più facili. Per un dolore persistente, chiedi un parere professionale; le scelte di esercizio di un’app non possono sostituirlo.`},{title:`Segnali urgenti`,text:`Nuovi cambiamenti nella vescica o nell’intestino, intorpidimento intorno all’inguine, debolezza grave o in peggioramento alle gambe o mal di schiena dopo un trauma importante richiedono una valutazione medica urgente.`},{title:`Usare TrainUp`,text:`Aggiungi la zona lombare come limitazione in Profilo, con una nota, così il piano sceglie esercizi adatti. Dopo ogni allenamento puoi aggiungere note e segnalare il dolore con la zona del corpo e l’esercizio. Se un esercizio provoca dolore, «Sento dolore» lo termina e lo tiene fuori dai tuoi piani finché non lo riprendi dal Profilo. TrainUp non diagnostica la causa del mal di schiena.`}];var n=[{label:`NHS: mal di schiena e segnali d’allarme urgenti`,url:`https://www.nhs.uk/conditions/back-pain/`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:o,sources:n};export{a as default,o as sections,n as sources};